        </template>
        <template v-if="page === 'violations'"><section class="panel"><h3>{{ admin ? '违规证据与纠错' : '我的违规记录' }}</h3><el-alert :title="admin ? '累计有效违规 ≥ 3 次自动限制预约；撤销误判后有效累计低于 3 次自动恢复。' : '迟到与爽约均计入有效累计；已撤销记录保留审计，不计入累计。'" type="info" :closable="false" show-icon /><el-table :data="violations" empty-text="暂无违规记录"><el-table-column prop="id" label="编号" width="75" /><el-table-column v-if="admin" label="学生" min-width="130"><template slot-scope="s">{{ s.row.userName }}<small class="cell-sub">{{ s.row.stuNo }}</small></template></el-table-column><el-table-column prop="orderId" label="订单" width="75" /><el-table-column label="类型" width="90"><template slot-scope="s">{{ s.row.type === 'LATE' ? '迟到' : '爽约' }}</template></el-table-column><el-table-column prop="reason" label="确认原因" min-width="200" /><el-table-column label="发生时间" min-width="175"><template slot-scope="s">{{ formatDate(s.row.occurredAt) }}</template></el-table-column><el-table-column label="状态" width="100"><template slot-scope="s"><el-tag :type="s.row.revoked ? 'info' : 'danger'" size="small">{{ s.row.revoked ? '已撤销' : '有效' }}</el-tag></template></el-table-column><el-table-column v-if="admin" label="操作" width="100"><template slot-scope="s"><el-button v-if="!s.row.revoked" type="text" :disabled="busy" @click="revoke(s.row)">撤销误判</el-button></template></el-table-column></el-table></section></template>
        <template v-if="page === 'users'"><section class="panel"><h3>学生账号与预约权限</h3><el-input v-model="userSearch" placeholder="搜索姓名或学号" clearable class="search-input" /><el-table :data="filteredUsers" empty-text="暂无学生账号"><el-table-column prop="stuNo" label="学号" min-width="130" /><el-table-column prop="userName" label="姓名" min-width="120" /><el-table-column prop="phone" label="联系方式" min-width="140" /><el-table-column prop="violateCount" label="有效累计违规" width="130" /><el-table-column label="预约权限" min-width="130"><template slot-scope="s"><el-tag :type="s.row.isBan ? 'danger' : 'success'">{{ s.row.isBan ? '受限' : '正常' }}</el-tag></template></el-table-column></el-table></section></template>
        <template v-if="page === 'dashboard'"><section class="hero"><div><p class="eyebrow">CAMPUS OVERVIEW</p><h1>今天的学习空间，一目了然</h1><p>统计由真实预约及管理员到场证据计算。</p></div><el-date-picker v-model="statisticsDate" type="date" value-format="yyyy-MM-dd" :clearable="false" @change="loadPage" /></section><div v-if="statistics" class="stats-grid"><div v-for="item in statisticCards" :key="item.label" class="stat-card"><span>{{ item.label }}</span><strong>{{ item.value }}</strong><small>{{ item.note }}</small></div></div><section v-if="statistics" class="panel"><div class="section-heading"><h3>各自习室资源利用</h3><div class="legend"><span>预约率</span><span>实际使用率</span></div></div><p class="muted">分母：当日统计范围内每间自习室 840 分钟，包含关闭与历史软删除房间；已取消不计预约，实际使用按到场至完成时间裁剪至订单和当日窗口。</p><div v-for="room in statistics.rooms" :key="room.roomId" class="chart-row"><strong>{{ room.roomNo }}</strong><div><el-progress :percentage="rate(room.bookingRate)" color="#167e86" /><el-progress :percentage="rate(room.usageRate)" color="#e3aa52" /></div><small>预约 {{ room.reservedMinutes }} 分钟 / 使用 {{ room.usedMinutes }} 分钟<br>可用 {{ room.availableMinutes }} 分钟</small></div><el-empty v-if="!statistics.rooms.length" description="该日暂无房间统计" /></section></template>
        <template v-if="page === 'profile'"><section class="panel profile-panel"><p class="eyebrow">YOUR PROFILE</p><h3>个人资料</h3><p class="muted">学号与角色不能自行修改，密码和哈希不会显示。</p><el-descriptions :column="1" border><el-descriptions-item label="账号">{{ user.stuNo }}</el-descriptions-item><el-descriptions-item label="角色">{{ admin ? '管理员' : '学生' }}</el-descriptions-item><el-descriptions-item label="有效累计违规">{{ user.violateCount }} 次</el-descriptions-item><el-descriptions-item label="预约权限">{{ user.isBan ? '受限' : '正常' }}</el-descriptions-item></el-descriptions><el-form ref="profileForm" :model="profile" :rules="profileRules" label-position="top"><el-form-item label="姓名" prop="userName"><el-input v-model.trim="profile.userName" maxlength="40" /></el-form-item><el-form-item label="联系方式" prop="phone"><el-input v-model.trim="profile.phone" maxlength="20" /></el-form-item><el-button type="primary" :loading="busy" @click="saveProfile">保存资料</el-button></el-form></section></template>
      </main><footer>静学 · 校园自习室预约系统 <span>整间独占 · 有序共享</span></footer>
    </div>
    <el-dialog :title="roomForm.id ? '编辑自习室' : '新增自习室'" :visible.sync="roomDialog" width="min(520px, 94vw)" :close-on-click-modal="false"><el-form ref="roomForm" :model="roomForm" :rules="roomRules" label-position="top"><el-form-item label="房间号" prop="roomNo"><el-input v-model.trim="roomForm.roomNo" maxlength="30" /></el-form-item><el-form-item label="楼层" prop="floor"><el-input v-model.trim="roomForm.floor" maxlength="30" /></el-form-item><el-form-item label="展示容量（不作为预约名额）" prop="capacity"><el-input-number v-model="roomForm.capacity" :min="1" :max="10000" /></el-form-item><el-form-item label="开放状态"><el-switch v-model="roomForm.status" active-value="OPEN" inactive-value="CLOSED" active-text="开放" inactive-text="关闭" /></el-form-item><el-form-item label="备注"><el-input v-model.trim="roomForm.remark" type="textarea" maxlength="200" show-word-limit /></el-form-item></el-form><span slot="footer"><el-button @click="roomDialog = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveRoom">保存</el-button></span></el-dialog>
  </div><div v-else class="initial-loading" v-loading="true">正在恢复登录会话…</div>
</template>

<script>
import { session, request, setSession, refreshUser } from './api.js'
import { localDate, orderMoment, isBookingDate, passwordError } from './time.js'
// 本组件负责登录、学生四页及管理员六页；列表均为真实 API 响应，不在页面补造数据。
const required = message => ({ required: true, message, trigger: 'blur' })
const profileRules = { userName: [required('请输入姓名'), { min: 1, max: 40, message: '姓名为 1–40 字' }], phone: [{ max: 20, message: '联系方式最多 20 字', trigger: 'blur' }] }
export default {
  name: 'CampusStudyApp',
  data() { return { session, busy: false, loading: false, error: '', auth: { stuNo: '', password: '', userName: '', phone: '' }, profile: { userName: '', phone: '' }, profileRules, authRules: { ...profileRules, stuNo: [required('请输入学号或账号')], password: [required('请输入密码'), { validator: (rule, value, callback) => { const message = passwordError(value); callback(message ? new Error(message) : undefined) }, trigger: 'blur' }] }, roomRules: { roomNo: [required('请输入房间号')], floor: [required('请输入楼层')], capacity: [{ type: 'number', min: 1, max: 10000, required: true, message: '容量为 1–10000 的整数' }] }, slot: { orderDate: localDate(1), startTime: '09:00', endTime: '10:00' }, queriedSlot: null, onlyAvailable: false, rooms: [], orders: [], violations: [], users: [], userSearch: '', orderFilter: '', statisticsDate: localDate(), statistics: null, roomDialog: false, roomForm: {}, statuses: { RESERVED: '待使用', COMPLETED: '已完成', CANCELLED: '已取消', NO_SHOW: '爽约' }, attendanceLabels: { UNKNOWN: '待确认', ARRIVED: '已到场', LATE: '迟到到场', NO_SHOW: '确认爽约' }, startOptions: { selectableRange: '08:00:00 - 21:59:59' }, dateOptions: { disabledDate: date => !isBookingDate(date) }, loadVersion: 0 } },
  computed: {
    user() { return this.session.user }, admin() { return this.user?.role === 'ADMIN' }, isAuth() { return this.$route.meta.public }, isRegister() { return this.$route.path === '/register' }, page() { return this.$route.path.split('/').pop() }, home() { return this.admin ? '/admin/dashboard' : '/rooms' },
    navigation() { const items = this.admin ? [['dashboard', '数据总览', 'el-icon-data-analysis'], ['rooms', '自习室管理', 'el-icon-office-building'], ['orders', '预约管理', 'el-icon-tickets'], ['users', '学生账号', 'el-icon-user'], ['violations', '违规管理', 'el-icon-warning-outline'], ['profile', '个人资料', 'el-icon-setting']] : [['rooms', '寻找自习室', 'el-icon-office-building'], ['orders', '我的预约', 'el-icon-tickets'], ['violations', '我的违规', 'el-icon-warning-outline'], ['profile', '个人资料', 'el-icon-user']]; return items.map(([path, label, icon]) => ({ path: (this.admin ? '/admin/' : '/') + path, label, icon })) },
    title() { return this.navigation.find(item => item.path === this.$route.path)?.label || '静学' },
    visibleRooms() { return this.rooms.filter(room => this.admin || !this.onlyAvailable || (room.status === 'OPEN' && room.available !== false)) },
    filteredOrders() { return this.orders.filter(order => !this.orderFilter || order.status === this.orderFilter) },
    filteredUsers() { return this.users.filter(user => `${user.userName} ${user.stuNo}`.includes(this.userSearch)) },
    endOptions() { return { selectableRange: '08:01:00 - 22:00:00' } },
    statisticCards() { return [{ label: '自习室总数', value: this.statistics.totalRooms, note: '资源概览' }, { label: '当日有效预约', value: this.statistics.totalOrders, note: '不含已取消订单' }, { label: '当日有效违规', value: this.statistics.totalViolations, note: '不含已撤销记录' }, { label: '预约率', value: this.rate(this.statistics.bookingRate) + '%', note: '预约时长 / 开放时长' }, { label: '实际使用率', value: this.rate(this.statistics.usageRate) + '%', note: '实际使用时长 / 开放时长' }] }
  },
  watch: { '$route.path': { immediate: true, handler() { this.error = ''; if (!this.isAuth) this.loadPage() } }, slot: { deep: true, handler() { this.queriedSlot = null } } },
  mounted() { window.addEventListener('session-expired', this.expired) },
  beforeDestroy() { window.removeEventListener('session-expired', this.expired) },
  methods: {
    /** 401 统一退出并导航；路由守卫和 API 失败消息共同保证失效会话不可继续操作。 */
    expired() { if (!this.isAuth) this.$router.replace('/login') },
    /** 表单登录/注册只发送白名单字段，不发送 role；成功依据服务端角色进入首页。 */
    async submitAuth() { if (this.busy) return; const valid = await this.$refs.authForm.validate().catch(() => false); if (!valid) return; await this.mutate(async () => { const payload = this.isRegister ? { ...this.auth } : { stuNo: this.auth.stuNo, password: this.auth.password }; const result = await request(this.isRegister ? '/auth/register' : '/auth/login', { method: 'POST', body: payload }); setSession(result.token, result.user); this.auth.password = ''; this.$router.replace(result.user.role === 'ADMIN' ? '/admin/dashboard' : '/rooms') }) },
    /** 登出请求成功才清除本地凭据；网络异常保留会话并提示重试。 */
    async logout() { await this.mutate(async () => { await request('/auth/logout', { method: 'POST' }); setSession(); this.$router.replace('/login') }) },
    /** 串行防重复提交，业务错误统一呈现后端消息；不会乐观修改订单/违规状态。 */
    async mutate(action) { if (this.busy) return; this.busy = true; try { await action() } catch (error) { if (error !== 'cancel' && error !== 'close') this.$message.error(error.message || '操作失败，请重试') } finally { this.busy = false } },
    /** 拉取当前路由数据；版本号丢弃旧路由响应，避免快切页面覆盖最新列表。 */
    async loadPage() { if (!this.session.token || this.isAuth) return; const version = ++this.loadVersion; const page = this.page; const admin = this.admin; this.loading = true; this.error = ''; try { await refreshUser(); if (version !== this.loadVersion) return; let result; if (page === 'rooms') result = await request('/rooms' + (this.queriedSlot && !admin ? '?' + new URLSearchParams({ date: this.queriedSlot.orderDate, startTime: this.queriedSlot.startTime, endTime: this.queriedSlot.endTime }) : '')); if (page === 'orders') result = await request(admin ? '/admin/orders' : '/orders/me'); if (page === 'violations') result = await request(admin ? '/admin/violations' : '/violations/me'); if (page === 'users') result = await request('/admin/users'); if (page === 'dashboard') result = await request('/admin/statistics?date=' + this.statisticsDate); if (version !== this.loadVersion) return; if (['rooms', 'orders', 'violations', 'users'].includes(page)) this[page] = result; if (page === 'dashboard') this.statistics = result; if (page === 'profile') this.profile = { userName: this.user.userName, phone: this.user.phone || '' } } catch (error) { if (version === this.loadVersion) this.error = error.message } finally { if (version === this.loadVersion) this.loading = false } },
    /** 时段输入校验仅改善交互；并发锁、重叠、封禁和时间边界仍由后端判定。 */
    async searchRooms() { if (!this.slot.orderDate || !this.slot.startTime || !this.slot.endTime || this.slot.startTime >= this.slot.endTime) return this.$message.warning('请选择完整且结束晚于开始的时段'); if (orderMoment(this.slot.orderDate, this.slot.startTime) <= new Date()) return this.$message.warning('预约开始时间必须晚于当前时间'); this.queriedSlot = { ...this.slot }; await this.loadPage() },
    /** 使用已查询时段确认整间预约；409 冲突提示后刷新房间，成功刷新权限及订单信息。 */
    async book(room) { const slot = { ...this.queriedSlot }; await this.mutate(async () => { await this.$confirm(`${slot.orderDate} ${slot.startTime}–${slot.endTime}，独占预约 ${room.roomNo} 整间自习室？`, '确认预约', { confirmButtonText: '确认预约', cancelButtonText: '再想想' }); try { await request('/orders', { method: 'POST', body: { roomId: room.id, ...slot } }); this.$message.success('预约成功，可在“我的预约”查看记录。') } finally { await this.loadPage() } }) },
    /** 学生取消边界严格在开始前；这里只控制按钮，后端再次核验所有权和时间。 */
    canCancel(order) { return order.status === 'RESERVED' && orderMoment(order.orderDate, order.startTime) > new Date() },
    /** 管理员合法按钮依据订单证据/时间展示；不可将已到场改成爽约，服务端最终裁定。 */
    allowedActions(order) { if (order.status !== 'RESERVED') return []; const now = new Date(); if (orderMoment(order.orderDate, order.startTime) > now) return []; if (['ARRIVED', 'LATE'].includes(order.attendance)) return orderMoment(order.orderDate, order.endTime) <= now ? [{ action: 'COMPLETE', label: '确认完成' }] : []; if (order.attendance !== 'UNKNOWN') return []; return [{ action: 'ARRIVED', label: '确认到场' }, { action: 'LATE', label: '确认迟到' }, { action: 'NO_SHOW', label: '确认爽约' }] },
    /** 要求管理员提供非空证据/纠错原因；取消对话框不发 API，敏感操作不静默执行。 */
    async reason(title) { const result = await this.$prompt('请填写已核实的事实、证据或操作原因（1–500 字）', title, { confirmButtonText: '确认执行', cancelButtonText: '取消', inputType: 'textarea', inputValidator: value => value && value.trim().length > 0 && value.trim().length <= 500 || '请输入 1–500 字原因' }); return result.value.trim() },
    /** 学生取消只带订单ID，管理员异常取消带原因；成功重新查询而非删除历史记录。 */
    async cancelOrder(order) { await this.mutate(async () => { const body = this.admin ? { reason: await this.reason('异常取消订单 #' + order.id) } : undefined; if (!this.admin) await this.$confirm('取消后将释放此时段，记录仍会保留。', '取消预约', { confirmButtonText: '确认取消', cancelButtonText: '保留预约' }); await request((this.admin ? '/admin/orders/' : '/orders/') + order.id + '/cancel', { method: 'POST', body }); this.$message.success('预约已取消'); await this.loadPage() }) },
    /** 确认到场/迟到/爽约/完成会影响证据与统计，迟到/爽约还会计入有效累计违规。 */
    async attendance(order, action) { await this.mutate(async () => { const reason = await this.reason('订单 #' + order.id + ' · ' + ({ ARRIVED: '确认到场', LATE: '确认迟到并记录违规', NO_SHOW: '确认爽约并记录违规', COMPLETE: '确认完成' }[action])); await request(`/admin/orders/${order.id}/attendance`, { method: 'POST', body: { action, reason } }); this.$message.success('状态与证据已保存'); await this.loadPage() }) },
    /** 撤销误判保留审计，累计与封禁由后端在同一事务重新计算，不提供任意解封开关。 */
    async revoke(violation) { await this.mutate(async () => { const reason = await this.reason('撤销违规 #' + violation.id); await request(`/admin/violations/${violation.id}/revoke`, { method: 'POST', body: { reason } }); this.$message.success('误判已撤销，预约权限已重新计算'); await this.loadPage() }) },
    /** 打开房间表单只复制可编辑字段；避免向后端提交 available 等计算字段。 */
    editRoom(room) { this.roomForm = room ? { id: room.id, roomNo: room.roomNo, floor: room.floor, capacity: room.capacity, status: room.status, remark: room.remark || '' } : { roomNo: '', floor: '', capacity: 20, status: 'OPEN', remark: '' }; this.roomDialog = true; this.$nextTick(() => this.$refs.roomForm?.clearValidate()) },
    /** 维护资源白名单；尚未结束的有效订单造成的关闭/删除冲突使用服务端错误解释。 */
    async saveRoom() { const valid = await this.$refs.roomForm.validate().catch(() => false); if (!valid) return; await this.mutate(async () => { const { id, ...body } = this.roomForm; await request('/admin/rooms' + (id ? '/' + id : ''), { method: id ? 'PUT' : 'POST', body }); this.roomDialog = false; this.$message.success('自习室已保存'); await this.loadPage() }) },
    /** 开关房间前确认；仅影响房间状态，预约历史不在前端篡改。 */
    async toggleRoom(room) { await this.mutate(async () => { await this.$confirm(`确认${room.status === 'OPEN' ? '关闭' : '开启'} ${room.roomNo}？`, '修改开放状态', { confirmButtonText: '确认', cancelButtonText: '取消' }); await request('/admin/rooms/' + room.id, { method: 'PUT', body: { roomNo: room.roomNo, floor: room.floor, capacity: room.capacity, remark: room.remark || '', status: room.status === 'OPEN' ? 'CLOSED' : 'OPEN' } }); this.$message.success('开放状态已更新'); await this.loadPage() }) },
    /** 删除二次确认；尚未结束的有效订单阻止删除，历史引用软删除保留，服务端最终核验。 */
    async deleteRoom(room) { await this.mutate(async () => { await this.$confirm(`确认删除 ${room.roomNo}？尚未结束的有效订单会阻止删除；历史记录通过软删除保留。`, '删除自习室', { type: 'warning', confirmButtonText: '确认删除', cancelButtonText: '取消' }); await request('/admin/rooms/' + room.id, { method: 'DELETE' }); this.$message.success('房间已删除'); await this.loadPage() }) },
    /** 修改姓名/联系方式白名单；成功刷新当前用户，不能提交角色、违规或封禁字段。 */
    async saveProfile() { const valid = await this.$refs.profileForm.validate().catch(() => false); if (!valid) return; await this.mutate(async () => { await request('/auth/me', { method: 'PUT', body: { ...this.profile } }); await refreshUser(); this.$message.success('资料已保存') }) },
    /** 以下展示函数只格式化服务端结果，零值/未知状态不自行推导为业务事实。 */
    shortTime(value) { return String(value || '').slice(0, 5) }, formatDate(value) { return value ? value.replace('T', ' ').slice(0, 19) : '—' }, statusType(status) { return ({ RESERVED: '', COMPLETED: 'success', CANCELLED: 'info', NO_SHOW: 'danger' })[status] || '' }, rate(value) { return Math.round(Math.max(0, Math.min(100, Number(value) || 0)) * 100) / 100 }
  }
}
</script>





